import type { NextRequest } from "next/server";
import {
  DrmProtectedError,
  fetchInfo,
  isSafeUrl,
  vimeoStreamsAreDrm,
  userFacingError,
  failureFingerprint,
  failureReason,
  NotMediaError,
  UnsupportedSiteError,
  type YtDlpFormat,
  type YtDlpInfo,
} from "@/lib/ytdlp";
import { embedFromPage, rememberedEmbed } from "@/lib/page-embeds";
import {
  X_NO_VIDEO,
  fetchTweetPhotos,
  rememberPhotos,
  tweetIdFrom,
  type XPhoto,
} from "@/lib/x-photos";
import { fetchTikTokPhotos, tiktokPhotoPost } from "@/lib/tiktok-photos";

/**
 * The quality list for a TikTok photo post: every slide under the form's
 * Photos tab, and the soundtrack under Audio, which the download reads from
 * the post's /video/ address (see api/jobs).
 */
function tiktokPhotoPayload(photos: XPhoto[], title: string | null) {
  return {
    ...xPhotoPayload(photos),
    title: title ?? (photos.length === 1 ? "Photo from TikTok" : "Photos from TikTok"),
    site: "TikTok",
    audio: AUDIO_OPTIONS,
  };
}

/** The quality list for an X photo post: its photos, nothing else. */
function xPhotoPayload(photos: XPhoto[]) {
  return {
    title: photos.length === 1 ? "Photo from X" : "Photos from X",
    thumbnail: photos[0].url,
    duration: null,
    uploader: null,
    site: "Twitter",
    video: [],
    audio: [],
    images: photos.map((p, i) => ({
      formatId: `xphoto-${i + 1}`,
      ext: p.ext,
      label:
        `Photo ${i + 1} (${p.ext.toUpperCase()})` +
        (p.width && p.height ? ` ${p.width}x${p.height}` : ""),
      filesize: null,
    })),
  };
}
import { clientIp, rateLimit } from "@/lib/rate-limit";
import { BusyError, lookupLimiter, MAX_LOOKUP_QUEUE } from "@/lib/concurrency";
import { logEvent } from "@/lib/analytics";
import { isShareLink, resolveShareLink } from "@/lib/share-links";

export const runtime = "nodejs";

type VideoTier = {
  formatId: string;
  ext: string;
  label: string;
  height: number;
  hasAudio: boolean;
  filesize: number | null;
};

type AudioOption = {
  id: string;
  label: string;
  audioFormat: "mp3" | "m4a";
  bitrate: number | null;
};

type ImageFormat = {
  formatId: string;
  ext: string;
  label: string;
  filesize: number | null;
};

// The quality ladder visitors actually recognise. Raw sites report dozens of
// near-duplicate streams (1220p WEBM, 916p MP4, ...); everything is snapped
// into these buckets so the list stays short and readable.
const VIDEO_TIERS = [2160, 1440, 1080, 720, 480, 360, 240, 144];

// Fixed MP3 choices, mirroring what people expect from a converter. The
// source is re-encoded to the chosen rate, so a high number can't add detail
// that was never in the original, it only sets the output bitrate.
const AUDIO_OPTIONS: AudioOption[] = [
  { id: "mp3-320", label: "320kbps", audioFormat: "mp3", bitrate: 320 },
  { id: "mp3-256", label: "256kbps", audioFormat: "mp3", bitrate: 256 },
  { id: "mp3-128", label: "128kbps", audioFormat: "mp3", bitrate: 128 },
  { id: "mp3-96", label: "96kbps", audioFormat: "mp3", bitrate: 96 },
  { id: "mp3-64", label: "64kbps", audioFormat: "mp3", bitrate: 64 },
  { id: "m4a", label: "M4A", audioFormat: "m4a", bitrate: null },
];

// Image posts (photo posts, TikTok slideshow frames, Pinterest images) come
// back from yt-dlp with no video and no audio codec, so they used to be
// filtered out. These extensions mark a format as an image instead.
const IMAGE_EXTS = new Set([
  "jpg",
  "jpeg",
  "png",
  "webp",
  "gif",
  "heic",
  "bmp",
  "tiff",
  "avif",
  // Drawings on Commons. They were listed as "480p" video.
  "svg",
]);

// Documents yt-dlp will not save: it skips unusual extensions so a site cannot
// slip an executable through it, and a PDF is not what this site is for.
// Commons lists a scanned PDF as one "source" format, which showed as "1080p"
// and then failed at the download.
const DOCUMENT_EXTS = new Set(["pdf", "djvu"]);

function isImageFormat(f: { ext?: string; vcodec?: string; acodec?: string }): boolean {
  const ext = (f.ext ?? "").toLowerCase();
  if (IMAGE_EXTS.has(ext)) return true;
  // Some extractors leave ext blank but mark both codecs "none" and give a
  // resolution; treat those as images too rather than dropping them.
  return f.vcodec === "none" && f.acodec === "none" && ext === "";
}

function imageLabel(f: { ext: string; width?: number; height?: number }): string {
  const kind = !f.ext ? "Photo" : f.ext === "svg" ? "Image (SVG)" : `Photo (${f.ext.toUpperCase()})`;
  if (f.width && f.height) return `${kind} ${f.width}x${f.height}`;
  return kind;
}

// The "p" number people expect is the short side of the frame: a phone clip
// recorded at 720x1220 is 720p, not 1220p. Using the short side stops vertical
// videos and Shorts from showing labels nobody recognises.
function qualityOf(f: { height?: number; width?: number }): number {
  const h = f.height ?? 0;
  const w = f.width ?? 0;
  if (h > 0 && w > 0) return Math.min(h, w);
  return h;
}

// Snaps a real height onto the ladder above, allowing a little slack so a
// 1078p or 1082p stream still lands in the 1080p bucket.
function tierFor(quality: number): number | null {
  for (const tier of VIDEO_TIERS) {
    if (quality >= tier * 0.9) return tier;
  }
  return null;
}

// Within one bucket, keep the stream that plays everywhere: MP4/H.264 first,
// then whichever carries the most bitrate.
/**
 * A stream the server can fetch from the CDN itself, rather than a manifest.
 *
 * This decides far more than it looks. A manifest format is a playlist of
 * further requests, so the CDN probe cannot check it and the job falls back to
 * pulling the media through the proxy. With the proxy being a relay on a home
 * connection, that is the difference between a download costing about 160 KB of
 * somebody's home data and costing the entire video.
 *
 * It was being chosen by accident: ranking was extension then bitrate, and
 * YouTube's HLS variants are mp4 with a healthy bitrate, so they won every tier
 * and 122 of the last 124 downloads went through the house.
 */
function isDirectlyFetchable(f: YtDlpFormat): boolean {
  const p = (f.protocol || "").toLowerCase();
  return p === "" || p === "https" || p === "http";
}

function isBetterVideo(a: YtDlpFormat, b: YtDlpFormat): boolean {
  // Before quality, because at the same height these are the same picture and
  // only one of them can be fetched without a detour. Sites that only publish
  // HLS are unaffected: this orders what is there, it does not discard
  // anything.
  const aDirect = isDirectlyFetchable(a) ? 1 : 0;
  const bDirect = isDirectlyFetchable(b) ? 1 : 0;
  if (aDirect !== bDirect) return aDirect > bDirect;
  const aMp4 = a.ext === "mp4" ? 1 : 0;
  const bMp4 = b.ext === "mp4" ? 1 : 0;
  if (aMp4 !== bMp4) return aMp4 > bMp4;
  return (a.tbr ?? 0) > (b.tbr ?? 0);
}

// A lookup costs a slow round trip to the source site (and, for YouTube, a
// metered proxy hop), yet the answer barely changes minute to minute. Holding
// recent results makes a re-paste of the same link instant and keeps repeat
// visitors off the proxy entirely.
const CACHE_TTL_MS = 10 * 60 * 1000;
const CACHE_MAX = 200;
const infoCache = new Map<string, { at: number; payload: unknown }>();

function cacheGet(key: string): unknown | null {
  const hit = infoCache.get(key);
  if (!hit) return null;
  if (Date.now() - hit.at > CACHE_TTL_MS) {
    infoCache.delete(key);
    return null;
  }
  // Refresh insertion order so busy links survive the size trim.
  infoCache.delete(key);
  infoCache.set(key, hit);
  return hit.payload;
}

function cacheSet(key: string, payload: unknown) {
  infoCache.set(key, { at: Date.now(), payload });
  while (infoCache.size > CACHE_MAX) {
    const oldest = infoCache.keys().next().value;
    if (oldest === undefined) break;
    infoCache.delete(oldest);
  }
}

export async function POST(request: NextRequest) {
  if (!rateLimit(`info:${clientIp(request)}`, 20, 60_000)) {
    return Response.json(
      { error: "Too many requests. Please slow down." },
      { status: 429 },
    );
  }
  if (lookupLimiter.queueLength > MAX_LOOKUP_QUEUE) {
    return Response.json(
      { error: "Server is busy. Try again in a moment." },
      { status: 503 },
    );
  }

  let body: { url?: string };
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid request body" }, { status: 400 });
  }

  const url = body.url?.trim();
  if (!url) {
    return Response.json({ error: "Paste a link first." }, { status: 400 });
  }
  if (!isSafeUrl(url)) {
    return Response.json({ error: "That link isn't valid." }, { status: 400 });
  }

  // Facebook's Share button produces fb.watch and /share/ addresses that no
  // extractor matches. Resolving to the canonical one here, before the cache is
  // consulted, means the lookup and the download agree on a single key and the
  // visitor is not told the link is from a site we cannot download from.
  const target = (await resolveShareLink(url)) ?? url;

  const cached = cacheGet(target);
  if (cached) return Response.json(cached);

  try {
    // A TikTok slideshow. yt-dlp has no extractor for /photo/ addresses, so
    // the slides are read from the post's own page instead.
    const tiktokPost = tiktokPhotoPost(target);
    if (tiktokPost) {
      const found = await fetchTikTokPhotos(tiktokPost);
      if (found.removed) throw new Error("ERROR: [TikTok] This post has been deleted");
      if (found.photos.length > 0) {
        rememberPhotos(target, found.photos);
        const payload = tiktokPhotoPayload(found.photos, found.title);
        void logEvent({ type: "lookup", ok: true, site: "TikTok" });
        cacheSet(target, payload);
        return Response.json(payload);
      }
    }
    let source = rememberedEmbed(target) ?? target;
    let info: YtDlpInfo;
    try {
      info = await fetchInfo(source);
    } catch (e) {
      // An X post with photos and no video. yt-dlp reads only video from X,
      // so the photos are listed from X's embed data instead.
      const tweetId = tweetIdFrom(target);
      if (tweetId && e instanceof Error && X_NO_VIDEO.test(e.message)) {
        const found = await fetchTweetPhotos(tweetId);
        if (found.photos.length > 0) {
          rememberPhotos(target, found.photos);
          const payload = xPhotoPayload(found.photos);
          void logEvent({ type: "lookup", ok: true, site: "Twitter" });
          cacheSet(target, payload);
          return Response.json(payload);
        }
        if (found.removed) throw new Error("ERROR: [twitter] This post has been deleted");
      }
      // Not a video address but a page with a player in it, such as the site
      // a Vimeo owner limited their video to. The player is found in the page
      // and read with the page as its referer, which is what that limit asks
      // for. Only after the extractor has nothing, so other links never pay.
      if (!(e instanceof UnsupportedSiteError) || source !== target) throw e;
      const embed = await embedFromPage(target);
      if (!embed) throw e;
      source = embed;
      info = await fetchInfo(source);
    }
    // Before the success is counted: a list of qualities that all fail at
    // the download is worse than saying so now.
    if (await vimeoStreamsAreDrm(info)) throw new DrmProtectedError();
    const all = (info.formats ?? []).filter((f) => !DOCUMENT_EXTS.has((f.ext ?? "").toLowerCase()));
    if (all.length === 0 && (info.formats?.length ?? 0) > 0) throw new NotMediaError();
    void logEvent({
      type: "lookup",
      ok: true,
      site: info.extractor_key ?? info.extractor ?? undefined,
    });

    const sizeOf = (f: YtDlpFormat) => f.filesize ?? f.filesize_approx ?? null;

    // Photo posts (Instagram carousels, TikTok slideshows) have no streams to
    // bucket, so they stay a plain list.
    const images: ImageFormat[] = all.filter(isImageFormat).map((f) => ({
      formatId: f.format_id,
      ext: f.ext,
      label: imageLabel(f),
      filesize: sizeOf(f),
    }));

    // A blank codec field means the site never reported one, not that the
    // track is missing. Facebook, X and various small hosts leave these empty,
    // so requiring a codec name here silently dropped every one of their
    // formats. Only an explicit "none" counts as absent.
    const hasVideo = (f: YtDlpFormat) => f.vcodec !== "none";
    const hasAudio = (f: YtDlpFormat) => f.acodec !== "none";

    // Cheapest audio stream that will be merged into a video-only pick. Used
    // to quote an honest combined size in the list.
    const audioSizes = all
      .filter((f) => !hasVideo(f) && hasAudio(f))
      .map(sizeOf)
      .filter((n): n is number => typeof n === "number" && n > 0)
      .sort((a, b) => a - b);
    const mergeAudioSize = audioSizes.length > 0 ? audioSizes[0] : 0;

    // One winner per rung of the ladder. Streams whose dimensions are missing
    // or too small to place are kept aside rather than thrown away.
    const best = new Map<number, YtDlpFormat>();
    const untiered: YtDlpFormat[] = [];
    for (const f of all) {
      if (!hasVideo(f) || isImageFormat(f)) continue;
      const tier = tierFor(qualityOf(f));
      if (tier === null) {
        untiered.push(f);
        continue;
      }
      const current = best.get(tier);
      if (!current || isBetterVideo(f, current)) best.set(tier, f);
    }

    const video: VideoTier[] = VIDEO_TIERS.filter((t) => best.has(t)).map((tier) => {
      const f = best.get(tier)!;
      const withAudio = hasAudio(f);
      const size = sizeOf(f);
      return {
        formatId: f.format_id,
        ext: f.ext,
        label: `${tier}p`,
        height: tier,
        hasAudio: withAudio,
        // A video-only stream gains the audio track it gets merged with.
        filesize: size === null ? null : withAudio ? size : size + mergeAudioSize,
      };
    });

    // Sites that report no usable dimensions still hand back real,
    // downloadable streams, so they are listed under whatever name they gave
    // instead of vanishing from the picker.
    //
    // yt-dlp lists formats worst first, so these are walked best first, the
    // way the ladder above reads. And a format named only "hd" or "sd" keeps
    // that name: Facebook hands a WARP exit exactly two such formats with no
    // height, both fell back to the label "MP4", and the duplicate check
    // threw the HD one away.
    const seenExtra = new Set<string>();
    for (const f of [...untiered].reverse()) {
      if (video.length >= VIDEO_TIERS.length + 6) break;
      const named = /^(?:hd|sd)$/i.test(f.format_id) ? f.format_id.toUpperCase() : "";
      const label =
        f.format_note?.trim() || f.resolution?.trim() || named || f.ext.toUpperCase();
      if (seenExtra.has(label)) continue;
      seenExtra.add(label);
      const withAudio = hasAudio(f);
      const size = sizeOf(f);
      video.push({
        formatId: f.format_id,
        ext: f.ext,
        label,
        height: 0,
        hasAudio: withAudio,
        filesize: size === null ? null : withAudio ? size : size + mergeAudioSize,
      });
    }

    // Only offer audio when the source actually has a soundtrack. A photo is
    // not one: Commons reports no codecs for its images, which read as "has
    // audio", so a photo was offered as MP3 only and the photo row, which sits
    // under the Video tab, was never shown.
    const audio: AudioOption[] = all.some((f) => !isImageFormat(f) && hasAudio(f))
      ? AUDIO_OPTIONS
      : [];

    const payload = {
      title: info.title ?? "Untitled",
      thumbnail: info.thumbnail ?? null,
      duration: info.duration ?? null,
      uploader: info.uploader ?? null,
      site: info.extractor_key ?? info.extractor ?? null,
      video,
      audio,
      images,
    };
    // Only worth remembering if there is something to download.
    if (video.length > 0 || images.length > 0) cacheSet(target, payload);
    return Response.json(payload);
  } catch (err) {
    // Which site, and why. Recorded together because either alone is close to
    // useless: a count of failures says something broke, and a code with no
    // platform says something broke somewhere. Successes carry the extractor's
    // own name; there is no extractor here to ask, so the hostname stands in.
    let failHost = "";
    try {
      failHost = new URL(target).hostname.toLowerCase().replace(/^www[.]/, "");
    } catch {
      failHost = "";
    }

    // Turned away at the queue rather than by the site itself.
    if (err instanceof BusyError) {
      void logEvent({ type: "lookup", ok: false, host: failHost, code: "BUSY" });
      return Response.json(
        { error: "We're handling a lot of links right now. Try again in a moment." },
        { status: 503 },
      );
    }
    let { error, status, code } = userFacingError(err);
    // A share link we could not follow reached the extractor as it was, and
    // "not a site we can download from" is wrong about Pinterest and Facebook.
    // Nearly always the post behind it was deleted.
    if (code === "UNSUPPORTED_SITE" && target === url && isShareLink(url)) {
      error =
        "That share link doesn't lead to a video any more, it may have been deleted. If it still opens for you, copy the link from the address bar and paste that instead.";
      status = 422;
      code = "SHARE_LINK_DEAD";
    }
    const fingerprint = failureFingerprint(err);
    void logEvent({ type: "lookup", ok: false, host: failHost, code });
    // Only the unexpected ones get a stack; private and removed videos are
    // normal. A 4xx still gets one line, because "that link is not from a site
    // we can download from" was how Facebook share links failed silently: a
    // whole URL shape breaking looks exactly like ordinary visitor typos until
    // someone counts them.
    if (status >= 500) {
      console.error(`yt-dlp info error code=${code} marks=${fingerprint}`, err);
    } else {
      console.warn(
        `lookup failed code=${code} host=${failHost} marks=${fingerprint} why=${failureReason(err)}`,
      );
    }
    // code and marks describe the shape of the failure, never its contents,
    // so a problem can be diagnosed without shell access to the server.
    return Response.json({ error, code, marks: fingerprint }, { status });
  }
}
